pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let s = input.as_str().unwrap_or("");
    let mut result = Vec::new();

    if s.is_empty() {
        return serde_json::json!(null);
    }

    let mut i = 0;
    while i < s.len() {
        if !('0'..='9').contains(&s[i]) && !('a'..='f').contains(&s[i]) && !('A'..='F').contains(&s[i]) {
            return serde_json::json!(null);
        }
        if i + 1 < s.len() && !('0'..='9').contains(&s[i + 1]) && !('a'..='f').contains(&s[i + 1]) && !('A'..='F').contains(&s[i + 1]) {
            return serde_json::json!(null);
        }
        i += 1;
    }

    if s.len() % 2 != 0 {
        return serde_json::json!(null);
    }

    for i in (0..s.len()).step_by(2) {
        let high = match s[i] {
            '0'..='9' => s[i] as u8 - b'0',
            'a'..='f' => s[i] as u8 - b'a' + 10,
            'A'..='F' => s[i] as u8 - b'A' + 10,
            _ => return serde_json::json!(null),
        };
        let low = match s[i + 1] {
            '0'..='9' => s[i + 1] as u8 - b'0',
            'a'..='f' => s[i + 1] as u8 - b'a' + 10,
            'A'..='F' => s[i + 1] as u8 - b'A' + 10,
            _ => return serde_json::json!(null),
        };
        result.push((high << 4 | low) as u8 as i64);
    }

    serde_json::json!(result)
}
